def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] != background and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            components.append(comp)

    out = [row[:] for row in grid]
    if components:
        top = min(components, key=lambda comp: min(r for r, c in comp))
        rightmost = max(c for r, c in top)
        rows = {r for r, c in top if c == rightmost}
        for r in rows:
            for c in range(rightmost + 1, w):
                out[r][c] = 1
    return out
